IDS=["YY2-003","YY2-004","YY2-005","ZY-001","ZY-002","ZY-003","ZY-004"]
assert set(P.keys())==set(IDS), (set(P.keys()), set(IDS))
assert len(P)==7
total=0
for cid in IDS:
    data=json.dumps(P[cid], ensure_ascii=False, indent=1).encode("utf-8")
    with open(os.path.join(BASE, cid+".json"), "wb") as f:
        f.write(data)
    total+=len(data)
#逐件精确打开自验
for cid in IDS:
    with open(os.path.join(BASE, cid+".json"), encoding="utf-8") as f:
        d=json.load(f)
    assert d["case_id"]==cid and set(d.keys())=={"case_id","prediction_text","basis","confidence","trigger"}
    assert "systems_used" in d["basis"]
print(f"WROTE {len(IDS)} files, total_bytes={total}, ids={IDS}")
trig={"changed_main":0,"reserve_used":0,"disputed":0}
for cid in IDS:
    t=P[cid]["trigger"]
    for k in trig:
        if t[k]: trig[k]+=1
print("TRIGGER_COUNTS", trig)
